//! The golden corpus reproduces: against the live crate, and against `oracle-v1`.
//!
//! The corpus was generated by the build frozen as `oracle-v1` and recomputed by the
//! Python engine and encoder before they were deleted (`tools/verify_corpus.py`, in the
//! history). Two tiers:
//!
//! * **fast**, under plain `cargo test`: a prefix of every section, live crate only;
//! * **full**, `#[ignore]`d: every game, against the live crate *and* the oracle -- the
//!   latter is what closes the chain from Python to whatever the live crate is today.
//!   `cargo test --release -p ttr-tools --test golden_corpus -- --ignored`.

use ttr_tools::corpus::{
    Corpus, HEURISTIC_SEEDS, OBS_SEEDS, RANDOM_SEEDS, Scope, check, configs, current_header,
};
use ttr_tools::engine::Live;

ttr_tools::engine_for!(
    /// The build frozen as `oracle-v1`.
    Oracle,
    ttr_oracle
);

fn load(map: &str, n: usize) -> Corpus {
    Corpus::load(map, n).unwrap_or_else(|e| panic!("{e}"))
}

#[test]
fn every_configuration_has_a_complete_corpus_under_the_current_versions() {
    for (map, n) in configs() {
        let corpus = load(map, n);
        assert_eq!(
            corpus.header,
            current_header(map, n),
            "{map} {n}P was recorded under a different contract, observation version, \
             board or rules"
        );
        assert_eq!(corpus.random.len(), RANDOM_SEEDS as usize);
        assert_eq!(corpus.random_obs.len(), OBS_SEEDS as usize);
        assert_eq!(corpus.heuristic.len(), HEURISTIC_SEEDS as usize);
    }
}

#[test]
fn a_prefix_of_every_section_reproduces_on_the_live_engine() {
    for (map, n) in configs() {
        let corpus = load(map, n);
        let scope = Scope::prefix(300, 6, 4);
        check(&Live::new(map, n), &corpus, &scope).unwrap_or_else(|e| panic!("{e}"));
    }
}

#[test]
fn a_tampered_corpus_is_caught() {
    // Guard the guard, once per section: flip one recorded value and the check must say
    // which game, in which section.
    let corpus = load("mini", 2);
    let engine = Live::new("mini", 2);
    let scope = Scope::prefix(3, 3, 3);

    let mut bad = corpus.clone();
    bad.random[2].chain ^= 1;
    let err = check(&engine, &bad, &scope).expect_err("a flipped chain went unnoticed");
    assert!(
        err.contains("random seed 2") && err.contains("chain"),
        "{err}"
    );

    let mut bad = corpus.clone();
    bad.random_obs[1].continuous ^= 1;
    let err = check(&engine, &bad, &scope).expect_err("a flipped digest went unnoticed");
    assert!(
        err.contains("random seed 1") && err.contains("continuous"),
        "{err}"
    );

    let mut bad = corpus.clone();
    bad.heuristic[0].actions.pop();
    let err = check(&engine, &bad, &scope).expect_err("a truncated replay went unnoticed");
    assert!(err.contains("heuristic seed 0"), "{err}");
}

#[test]
#[ignore = "every game: run with --release -- --ignored"]
fn the_whole_corpus_reproduces_on_the_live_engine() {
    for (map, n) in configs() {
        check(&Live::new(map, n), &load(map, n), &Scope::all()).unwrap_or_else(|e| panic!("{e}"));
    }
}

#[test]
#[ignore = "every game: run with --release -- --ignored"]
fn the_whole_corpus_reproduces_on_oracle_v1() {
    // Play, scores and hash chains in full; not the observation digests, which the corpus
    // records under the live OBS_VERSION and the frozen build encodes under version 1.
    for (map, n) in configs() {
        let scope = Scope::all().without_observations();
        check(&Oracle::new(map, n), &load(map, n), &scope).unwrap_or_else(|e| panic!("{e}"));
    }
}
